public boolean process()
{
    boolean avaValid;
    str     errorMessage;


    avaValid = next process();

    if (mode == WHSWorkExecuteMode::AVACoilCalculator)
    {
        WMSLocation location = controlData.wmsLocation();

        if (!controlData.validateItemInLocation(fieldValues.parmItemId()))
        {
            fieldValues.parmItemId('');
            return this.fail("@WAX774");
        }

        [avaValid, errorMessage] = AVACoilCalculator::validateItem(fieldValues.parmItemId());

        if (!avaValid)
        {
            fieldValues.parmItemId('');
            return this.fail(errorMessage);
        }
    }

    return avaValid;
}

protected boolean mustPopulate()
{
    boolean  avaMustPopulate;

    avaMustPopulate = next mustPopulate();

    switch (mode)
    {
        case WHSWorkExecuteMode::AVACoilCalculator:
            avaMustPopulate = false;
            break;
    }

    return avaMustPopulate;
}
